# 一键部署到 Hugging Face Spaces`n# 用法: .\deploy-hf.ps1 -HfUser <HF用户名> -HfToken <hf_令牌> [-SpaceName ai-stock-research]`nparam(`n    [Parameter(Mandatory=$true)][string]$HfUser,`n    [Parameter(Mandatory=$true)][string]$HfToken,`n    [string]$SpaceName = 'ai-stock-research'`n)`n$ErrorActionPreference = 'Stop'`n`n$src = $PSScriptRoot`n$tmp = Join-Path $env:TEMP ('hf-space-' + $SpaceName)`n`nWrite-Host '==> 克隆 Space ...'`nif (Test-Path $tmp) { Remove-Item $tmp -Recurse -Force }`n$repoUrl = 'https://' + $HfUser + ':' + $HfToken + '@huggingface.co/spaces/' + $HfUser + '/' + $SpaceName`ngit clone $repoUrl $tmp 2>&1 | Out-Null`nif (-not (Test-Path (Join-Path $tmp '.git'))) { throw '克隆失败：检查用户名/令牌/Space(Docker类型) 是否正确' }`n`nWrite-Host '==> 同步项目文件 ...'`n$exclude = @('.git', 'vendor', '.cache', '.env', 'deploy-hf.ps1', 'render.yaml')`nGet-ChildItem $src -Force | Where-Object { $exclude -notcontains $_.Name } | ForEach-Object {`n    Copy-Item $_.FullName (Join-Path $tmp $_.Name) -Recurse -Force`n}`n`n# README 前加 HF Space frontmatter（Docker SDK + 端口 7860）`n$readmePath = Join-Path $tmp 'README.md'`n$readme = Get-Content $readmePath -Raw -ErrorAction SilentlyContinue`n$nl = [char]10`n$front = '---' + $nl + 'title: AI Stock Research' + $nl + 'emoji: chart_increasing' + $nl + 'colorFrom: blue' + $nl + 'colorTo: indigo' + $nl + 'sdk: docker' + $nl + 'app_port: 7860' + $nl + 'pinned: false' + $nl + '---' + $nl + $nl`nif ($readme -notmatch '^---') {`n    Set-Content $readmePath -Value ($front + $readme) -Encoding UTF8 -NoNewline`n}`n`nWrite-Host '==> 提交并推送（HF 自动开始构建） ...'`ngit -C $tmp add -A`ngit -C $tmp -c user.name='deploy' -c user.email='deploy@local' commit -m 'deploy: AI stock research web app' 2>&1 | Out-Null`ngit -C $tmp push origin main 2>&1 | Out-Null`nRemove-Item $tmp -Recurse -Force   # 清理令牌痕迹`n`nWrite-Host ''`nWrite-Host '推送完成！HF 正在构建 Docker 镜像（首次约 5-10 分钟）' -ForegroundColor Green`nWrite-Host ('  Space: https://huggingface.co/spaces/' + $HfUser + '/' + $SpaceName)`nWrite-Host ('  应用:   https://' + $HfUser + '-' + $SpaceName + '.hf.space')`nWrite-Host ''`nWrite-Host '设置 Secrets（必须，否则妙想/研报不可用）:' -ForegroundColor Yellow`nWrite-Host '  网页: Space -> Settings -> Variables and secrets:'`nWrite-Host '    EM_API_KEY  = <妙想KEY>'`nWrite-Host '    LLM_API_KEY = <DeepSeek KEY>'
